from __future__ import annotations

from collections.abc import Callable
from typing import Any

import streamlit as st

from optichub.grpc_client import ModuleInfo, configure_module, start_module, stop_module


def tab_primocache_monitor(
    host: str,
    port: int,
    info: ModuleInfo | None,
    cfg: dict[str, Any],
    running: bool,
    can_stop: bool,
    key: Callable[[str], str],
) -> None:
    poll_s = st.number_input(
        "Poll interval (seconds)",
        min_value=1.0,
        max_value=3_600.0,
        value=float(cfg.get("poll_interval_s", 15.0)),
        step=1.0,
        key=key("m_pc_poll"),
    )
    payload = {"poll_interval_s": float(poll_s)}

    c1, c2 = st.columns(2)
    with c1:
        if st.button("Start", type="primary", disabled=running, key=key("m_pc_start")):
            ok, msg = start_module(host, port, module="primocache_monitor", config=payload)
            if ok:
                st.success(msg or "started")
                st.rerun()
            else:
                st.error(msg)
    with c2:
        if st.button("Stop", disabled=not can_stop, key=key("m_pc_stop")):
            ok, msg = stop_module(host, port, module="primocache_monitor")
            if ok:
                st.success(msg or "stopped")
                st.rerun()
            else:
                st.error(msg)

    if st.button("Apply config (restart module)", disabled=not running, key=key("m_pc_apply")):
        ok, msg = configure_module(host, port, module="primocache_monitor", config=payload)
        if ok:
            st.success(msg or "reconfigured")
            st.rerun()
        else:
            st.error(msg)
